    42  type MenuItem = {
    43      icon: IconAsset;
    44      text: string;
    45      onSelected: () => void;
    46      shouldCallAfterModalHide?: boolean;
    47  };
    48
    49  type AvatarWithImagePickerProps = {
    50      /** Avatar source to display */
    51      source?: AvatarSource;
    52
    53      /** Account id of user for which avatar is displayed  */
    54      avatarID?: number | string;
    55
    56      /** Additional style props */
    57      style?: StyleProp<ViewStyle>;
    58
    59      /** Additional style props for disabled picker */
