    73
    74      /** Whether we are using the default avatar */
    75      isUsingDefaultAvatar?: boolean;
    76
    77      /** Size of Indicator */
    78      size?: typeof CONST.AVATAR_SIZE.XLARGE | typeof CONST.AVATAR_SIZE.LARGE | typeof CONST.AVATAR_SIZE.DEFAULT;
    79
    80      /** A fallback avatar icon to display when there is an error on loading avatar from remote URL. */
