    82
    83      /** Denotes whether it is an avatar or a workspace avatar */
    84      type?: typeof CONST.ICON_TYPE_AVATAR | typeof CONST.ICON_TYPE_WORKSPACE;
    85
    86      /** Image crop vector mask */
    87      editorMaskImage?: IconAsset;
    88
    89      /** Additional style object for the error row */
    90      errorRowStyles?: StyleProp<ViewStyle>;
    91
    92      /** A function to run when the X button next to the error is clicked */
    93      onErrorClose?: () => void;
    94
    95      /** The type of action that's pending  */
    96      pendingAction?: OnyxCommon.PendingAction;
    97
    98      /** The errors to display  */
    99      errors?: OnyxCommon.Errors | null;
   100
   101      /** Title for avatar preview modal */
   102      headerTitle?: string;
   103
   104      /** Avatar source for avatar preview modal */
   105      previewSource?: AvatarSource;
   106
   107      /** File name of the avatar */
   108      originalFileName?: string;
   109
   110      /** Whether navigation is focused */
   111      isFocused: boolean;
   112
   113      /** Style applied to the avatar */
   114      avatarStyle: StyleProp<ViewStyle & ImageStyle>;
   115
   116      /** Indicates if picker feature should be disabled */
   117      disabled?: boolean;
   118
   119      /** Executed once click on view photo option */
   120      onViewPhotoPress?: () => void;
