   131      /** Determines if a style utility function should be used for calculating the PopoverMenu anchor position. */
   132      shouldUseStyleUtilityForAnchorPosition?: boolean;
   133  };
   134
   135  function AvatarWithImagePicker({
   136      isFocused,
   137      DefaultAvatar = () => null,
   138      style,
   139      disabledStyle,
   140      editIconStyle,
   141      pendingAction,
   142      errors,
   143      errorRowStyles,
   144      onErrorClose = () => {},
   145      source = '',
   146      avatarID,
   147      fallbackIcon = Expensicons.FallbackAvatar,
   148      size = CONST.AVATAR_SIZE.DEFAULT,
   149      type = CONST.ICON_TYPE_AVATAR,
   150      headerTitle = '',
   151      previewSource = '',
   152      originalFileName = '',
   153      isUsingDefaultAvatar = false,
   154      onImageSelected = () => {},
   155      onImageRemoved = () => {},
   156      editorMaskImage,
   157      avatarStyle,
   158      disabled = false,
   159      onViewPhotoPress,
   160      enablePreview = false,
   161      shouldDisableViewPhoto = false,
   162      editIcon = Expensicons.Pencil,
   163      shouldUseStyleUtilityForAnchorPosition = false,
   164  }: AvatarWithImagePickerProps) {
   165      const theme = useTheme();
   166      const styles = useThemeStyles();
   167      const {windowWidth} = useWindowDimensions();
   168      const [popoverPosition, setPopoverPosition] = useState({horizontal: 0, vertical: 0});
   169      const [isMenuVisible, setIsMenuVisible] = useState(false);
   170      const [errorData, setErrorData] = useState<ErrorData>({validationError: null, phraseParam: {}});
   171      const [isAvatarCropModalOpen, setIsAvatarCropModalOpen] = useState(false);
   172      const [imageData, setImageData] = useState({
   173          uri: '',
   174          name: '',
   175          type: '',
   176      });
   177      const anchorRef = useRef<View>(null);
   178      const {translate} = useLocalize();
   179
   180      const setError = (error: TranslationPaths | null, phraseParam: Record<string, unknown>) => {
   181          setErrorData({
   182              validationError: error,
   183              phraseParam,
   184          });
   185      };
   186
   187      useEffect(() => {
   188          if (isFocused) {
   189              return;
   190          }
   191
   192          // Reset the error if the component is no longer focused.
   193          setError(null, {});
   194      }, [isFocused]);
   195
   196      useEffect(() => {
   197          setError(null, {});
   198      }, [source, avatarID]);
   199
   200      /**
   201       * Check if the attachment extension is allowed.
   202       */
   203      const isValidExtension = useCallback((image: FileObject): boolean => {
   204          const {fileExtension} = FileUtils.splitExtensionFromFileName(image?.name ?? '');
   205          return CONST.AVATAR_ALLOWED_EXTENSIONS.some((extension) => extension === fileExtension.toLowerCase());
   206      }, []);
   207
   208      /**
   209       * Check if the attachment size is less than allowed size.
   210       */
   211      const isValidSize = useCallback((image: FileObject): boolean => (image?.size ?? 0) < CONST.AVATAR_MAX_ATTACHMENT_SIZE, []);
   212
   213      /**
   214       * Check if the attachment resolution matches constraints.
   215       */
   216      const isValidResolution = (image: FileObject): Promise<boolean> =>
   217          getImageResolution(image).then(
   218              ({height, width}) => height >= CONST.AVATAR_MIN_HEIGHT_PX && width >= CONST.AVATAR_MIN_WIDTH_PX && height <= CONST.AVATAR_MAX_HEIGHT_PX && width <= CONST.AVATAR_MAX_WIDTH_PX,
   219          );
   220
   221      /**
   222       * Validates if an image has a valid resolution and opens an avatar crop modal
   223       */
   224      const showAvatarCropModal = useCallback(
   225          (image: FileObject) => {
   226              if (!isValidExtension(image)) {
   227                  setError('avatarWithImagePicker.notAllowedExtension', {allowedExtensions: CONST.AVATAR_ALLOWED_EXTENSIONS});
   228                  return;
   229              }
   230              if (!isValidSize(image)) {
   231                  setError('avatarWithImagePicker.sizeExceeded', {maxUploadSizeInMB: CONST.AVATAR_MAX_ATTACHMENT_SIZE / (1024 * 1024)});
   232                  return;
   233              }
   234
   235              isValidResolution(image).then((isValid) => {
   236                  if (!isValid) {
   237                      setError('avatarWithImagePicker.resolutionConstraints', {
   238                          minHeightInPx: CONST.AVATAR_MIN_HEIGHT_PX,
   239                          minWidthInPx: CONST.AVATAR_MIN_WIDTH_PX,
   240                          maxHeightInPx: CONST.AVATAR_MAX_HEIGHT_PX,
   241                          maxWidthInPx: CONST.AVATAR_MAX_WIDTH_PX,
   242                      });
   243                      return;
   244                  }
   245
   246                  setIsAvatarCropModalOpen(true);
   247                  setError(null, {});
   248                  setIsMenuVisible(false);
   249                  setImageData({
   250                      uri: image.uri ?? '',
   251                      name: image.name ?? '',
   252                      type: image.type ?? '',
   253                  });
   254              });
   255          },
   256          [isValidExtension, isValidSize],
   257      );
   258
   259      const hideAvatarCropModal = () => {
   260          setIsAvatarCropModalOpen(false);
   261      };
   262
   263      /**
   264       * Create menu items list for avatar menu
   265       */
   266      const createMenuItems = (openPicker: OpenPicker): MenuItem[] => {
   267          const menuItems: MenuItem[] = [
   268              {
   269                  icon: Expensicons.Upload,
